// Times sets number of times Messager.SetType should be invoked
func (mmSetType *mMessagerMockSetType) Times(n uint64) *mMessagerMockSetType {
	if n == 0 {
		mmSetType.mock.t.Fatalf("Times of MessagerMock.SetType mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmSetType.expectedInvocations, n)
	mmSetType.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmSetType
}

func (mmSetType *mMessagerMockSetType) invocationsDone() bool {
	if len(mmSetType.expectations) == 0 && mmSetType.defaultExpectation == nil && mmSetType.mock.funcSetType == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmSetType.mock.afterSetTypeCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmSetType.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// SetType implements mm_interfaces.Messager
func (mmSetType *MessagerMock) SetType(v string) {
	mm_atomic.AddUint64(&mmSetType.beforeSetTypeCounter, 1)
	defer mm_atomic.AddUint64(&mmSetType.afterSetTypeCounter, 1)

	mmSetType.t.Helper()

	if mmSetType.inspectFuncSetType != nil {
		mmSetType.inspectFuncSetType(v)
	}

	mm_params := MessagerMockSetTypeParams{v}

	// Record call args
	mmSetType.SetTypeMock.mutex.Lock()
	mmSetType.SetTypeMock.callArgs = append(mmSetType.SetTypeMock.callArgs, &mm_params)
	mmSetType.SetTypeMock.mutex.Unlock()

	for _, e := range mmSetType.SetTypeMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return
		}
	}

	if mmSetType.SetTypeMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmSetType.SetTypeMock.defaultExpectation.Counter, 1)
		mm_want := mmSetType.SetTypeMock.defaultExpectation.params
		mm_want_ptrs := mmSetType.SetTypeMock.defaultExpectation.paramPtrs

		mm_got := MessagerMockSetTypeParams{v}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.v != nil && !minimock.Equal(*mm_want_ptrs.v, mm_got.v) {
				mmSetType.t.Errorf("MessagerMock.SetType got unexpected parameter v, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSetType.SetTypeMock.defaultExpectation.expectationOrigins.originV, *mm_want_ptrs.v, mm_got.v, minimock.Diff(*mm_want_ptrs.v, mm_got.v))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmSetType.t.Errorf("MessagerMock.SetType got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmSetType.SetTypeMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		return

	}
	if mmSetType.funcSetType != nil {
		mmSetType.funcSetType(v)
		return
	}
	mmSetType.t.Fatalf("Unexpected call to MessagerMock.SetType. %v", v)

}

